//! Std-only smoke run of the `firewall_gw_trajectory` libFuzzer target
//! (`fuzz/fuzz_targets/`): the same harness
//! (`fuzz/harness/firewall_gw_trajectory.rs`, included by path) driven by
//! the deterministic mutator in `fuzz/harness/smoke.rs` over the committed
//! seed corpus. See `fuzz/README.md`. The seeds are (re)generated by
//! `regenerate_seeds` (run with `--ignored`).

#[path = "../../../fuzz/harness/firewall_gw_trajectory.rs"]
mod firewall_gw_trajectory;
#[path = "../../../fuzz/harness/smoke.rs"]
mod smoke;

use firewall_gw_trajectory::record;
use robodr_firewall_gw::testkit::TRAJ_JOINTS;
use robodr_firewall_gw::trajectory::{encode, GoalHeader, Point};

const DIR: &str = env!("CARGO_MANIFEST_DIR");

fn pts(n: usize, speed: f64) -> Vec<Point> {
    (0..n)
        .map(|i| {
            let t = 0.1 * (i as f64 + 1.0);
            Point {
                velocities: vec![speed, 0.0, -speed],
                ..Point::at(t, &[speed * t, 0.2, -speed * t])
            }
        })
        .collect()
}

fn seeds() -> Vec<(&'static str, Vec<u8>)> {
    let mut out = Vec::new();
    for (name, flags) in [
        ("seed-reject.bin", 0u8),
        ("seed-time-scale.bin", 1),
        ("seed-cyclone-probe.bin", 2 | 4),
    ] {
        let goal_header = if flags & 2 != 0 {
            GoalHeader::Cyclone
        } else {
            GoalHeader::None
        };
        let mut v = vec![flags];
        v.extend(record(0, &encode(&TRAJ_JOINTS, &pts(5, 0.5), false, None)));
        v.extend(record(0, &encode(&TRAJ_JOINTS, &pts(5, 2.0), true, None)));
        v.extend(record(
            1,
            &encode(
                &TRAJ_JOINTS,
                &pts(3, 0.4),
                false,
                Some((goal_header, [3; 16])),
            ),
        ));
        v.extend(record(0, &encode(&TRAJ_JOINTS, &[], false, None)));
        v.extend(record(2, &encode(&TRAJ_JOINTS, &pts(2, 0.1), false, None)));
        out.push((name, v));
    }
    out
}

#[test]
#[ignore = "regenerates fuzz/corpus/firewall_gw_trajectory"]
fn regenerate_seeds() {
    let dir = smoke::corpus_dir(DIR, "firewall_gw_trajectory");
    std::fs::create_dir_all(&dir).unwrap();
    for (name, bytes) in seeds() {
        std::fs::write(dir.join(name), bytes).unwrap();
    }
}

#[test]
fn committed_seeds_match_the_generator() {
    let committed = smoke::corpus(DIR, "firewall_gw_trajectory");
    for (_, s) in seeds() {
        assert!(
            committed.contains(&s),
            "a seed changed: run regenerate_seeds"
        );
    }
}

#[test]
fn firewall_gw_trajectory_smoke() {
    let mut seeds: Vec<Vec<u8>> = smoke::corpus(DIR, "firewall_gw_trajectory");
    seeds.extend(self::seeds().into_iter().map(|(_, s)| s));
    smoke::run(
        "firewall_gw_trajectory",
        &seeds,
        0x6a7e_0002,
        &firewall_gw_trajectory::run,
    );
}
